function lineTotal(item) {
  return round2(item.price * item.qty);
}

function grandTotal(items) {
  return round2(items.map(lineTotal).reduce((a, b) => a + b, 0));
}

const items = [
    { price: 0.125, qty: 1 },
    { price: 0.125, qty: 1 },
    { price: 0.125, qty: 1 },
  ];
  assert.strictEqual(grandTotal(items), 0.38);

package textutil

import "strings"

func Normalize(s string) string {
	return strings.TrimSpace(s)
}

// Merge overlays src onto dst: keys present in src replace keys in dst.
func Merge(dst, src map[string]string) map[string]string {
	out := map[string]string{}
	for k, v := range src {
		out[k] = v
	}
	for k, v := range dst {
		out[k] = v
	}
	return out
}

function slugify(text) {
  return text.toLowerCase().replace(/ /g, "-");
}
